result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pw-menu/public/menu.js", "content": "(function () {
  'use strict';

  var button = document.getElementById('menu-button');
  var list = document.getElementById('menu-list');
  var items = Array.prototype.slice.call(list.querySelectorAll('[role="menuitem"]'));

  function isOpen() {
    return button.getAttribute('aria-expanded') === 'true';
  }

  function open() {
    button.setAttribute('aria-expanded', 'true');
    list.classList.add('open');
  }

  function close() {
    if (!isOpen()) return;
    button.setAttribute('aria-expanded', 'false');
    list.classList.remove('open');
  }

  function focusItem(index) {
    var len = items.length;
    // Wrap around both ends.
    index = ((index % len) + len) % len;
    items[index].focus();
  }

  function currentItemIndex() {
    var i = items.indexOf(document.activeElement);
    return i === -1 ? null : i;
  }

  button.addEventListener('click', function () {
    isOpen() ? close() : open();
  });

  button.addEventListener('keydown', function (event) {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        if (!isOpen()) open();
        focusItem(currentItemIndex() === null ? 0 : currentItemIndex() + 1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        if (!isOpen()) open();
        focusItem(currentItemIndex() === null ? items.length - 1 : currentItemIndex() - 1);
        break;
    }
  });

  list.addEventListener('keydown', function (event) {
    var current = currentItemIndex();
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        focusItem(current + 1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        focusItem(current - 1);
        break;
      case 'Escape':
        event.preventDefault();
        close();
        button.focus();
        break;
      case 'Tab':
        // Tab out of the menu closes it without swallowing navigation.
        close();
        break;
    }
  });

  document.addEventListener('click', function (event) {
    if (!isOpen()) return;
    var target = event.target;
    if (button.contains(target) || list.contains(target)) return;
    close();
  });

  // Safety net (e.g. programmatic focus changes): losing focus from both
  // button and menu closes it.
  document.addEventListener('focusin', function (event) {
    if (!isOpen()) return;
    var t = event.target;
    if (button.contains(t) || list.contains(t)) return;
    close();
  });
})();
"})
