result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pw-menu/tests/menu.spec.js", "content": "const { test, expect } = require('@playwright/test');

const BUTTON = '#menu-button';
const LIST = '#menu-list';
const ITEMS = ['#menu-list a[href="#open"]', '#menu-list a[href="#save"]', '#menu-list a[href="#rename"]', '#menu-list a[href="#delete"]'];

async function expectFocused(page, selector) {
  await expect(page.locator(selector)).toBeFocused();
}

test.beforeEach(async ({ page }) => {
  await page.goto('/');
  await expect(page.locator(BUTTON)).toHaveAttribute('aria-expanded', 'false');
  await page.locator(BUTTON).focus();
});

test('Enter opens the menu and ArrowDown moves through all items with wrap', async ({ page }) => {
  const button = page.locator(BUTTON);
  await button.press('Enter');
  await expect(button).toHaveAttribute('aria-expanded', 'true');

  // First Enter leaves focus on the button; first ArrowDown enters the menu.
  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[0]);

  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[1]);
  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[2]);
  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[3]);

  // Wrap forward past the last item.
  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[0]);

  // Wrap backward before the first item.
  await page.keyboard.press('ArrowUp');
  await expectFocused(page, ITEMS[3]);
  await page.keyboard.press('ArrowUp');
  await expectFocused(page, ITEMS[2]);
  await page.keyboard.press('ArrowUp');
  await expectFocused(page, ITEMS[1]);
  await page.keyboard.press('ArrowUp');
  await expectFocused(page, ITEMS[0]);
  await page.keyboard.press('ArrowUp');
  await expectFocused(page, ITEMS[3]);
});

test('arrow to third item and assert activeElement text via toBeFocused', async ({ page }) => {
  await page.locator(BUTTON).press('Enter');
  await expect(page.locator(BUTTON)).toHaveAttribute('aria-expanded', 'true');

  await page.keyboard.press('ArrowDown'); // -> item 1
  await page.keyboard.press('ArrowDown'); // -> item 2
  await page.keyboard.press('ArrowDown'); // -> item 3

  await expectFocused(page, ITEMS[2]);
  const activeText = await page.evaluate(() => document.activeElement.textContent.trim());
  expect(activeText).toBe('Rename file');
  // Belt and braces: activeElement is exactly the third link.
  await expect(page.locator(`${ITEMS[2]}:scope`)).toBeFocused();
});

test('ArrowUp from the button opens with focus on last item', async ({ page }) => {
  await page.locator(BUTTON).press('ArrowUp');
  await expect(page.locator(BUTTON)).toHaveAttribute('aria-expanded', 'true');
  await expectFocused(page, ITEMS[3]);
});

test('Escape closes the menu and returns focus to the button', async ({ page }) => {
  const button = page.locator(BUTTON);
  await button.press('Enter');
  await expect(button).toHaveAttribute('aria-expanded', 'true');

  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[0]);
  await page.keyboard.press('Escape');

  await expect(button).toHaveAttribute('aria-expanded', 'false');
  await expect(button).toBeFocused();
});

test('clicking outside closes the menu (aria-expanded false)', async ({ page }) => {
  const button = page.locator(BUTTON);
  await button.click();
  await expect(button).toHaveAttribute('aria-expanded', 'true');

  await page.mouse.click(400, 400); // outside both button and menu
  await expect(button).toHaveAttribute('aria-expanded', 'false');
});

test('Tab out of the menu closes it', async ({ page }) => {
  const button = page.locator(BUTTON);
  await button.focus();
  await button.press('Enter');
  await page.keyboard.press('ArrowDown');
  await expectFocused(page, ITEMS[0]);
  await expect(button).toHaveAttribute('aria-expanded', 'true');

  await page.keyboard.press('Tab');
  await expect(button).toHaveAttribute('aria-expanded', 'false');
});
"})
